state.activity=state.activity||[];state.emailSubjects=state.emailSubjects||{};state.sequenceApprovals=state.sequenceApprovals||{};state.contactAssignments=state.contactAssignments||{};state.followups=state.followups||[];state.researchRuns=state.researchRuns||[];
function saved(label){state.activity.unshift({label,time:new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})});state.activity=state.activity.slice(0,30);persist();toast(label)}
let inspectorTrail=[],inspectorCurrent=null,inspectorReturnFocus=null;
function renderInspector(){const d=inspectorCurrent;$('#drawer').innerHTML=`<div class="inspector-top"><div>${inspectorTrail.length?ib('Back','inspectorBack()','chevron'): '<span class="micro-label">NINE-67 / '+(current<0?'WORKSPACE':toolsList[current][0].toUpperCase())+'</span>'}</div>${ib('Close','closeDrawer()','plus')}</div><h1 id="inspectorHeading" class="inspector-title">${esc(d.title)}</h1>${d.body}`;$('#overlay').hidden=false;$('#drawer').scrollTop=0;$('#drawer').setAttribute('role','dialog');$('#drawer').setAttribute('aria-modal','true');$('#drawer').setAttribute('aria-labelledby','inspectorHeading');$('#drawer').setAttribute('tabindex','-1');$('#drawer').focus();}
draw=function(title,body){if($('#overlay').hidden)inspectorReturnFocus=document.activeElement;if(!$('#overlay').hidden&&inspectorCurrent)inspectorTrail.push(inspectorCurrent);else inspectorTrail=[];inspectorCurrent={title,body};renderInspector()};
closeDrawer=function(){$('#overlay').hidden=true;inspectorTrail=[];inspectorCurrent=null;if(inspectorReturnFocus?.isConnected)inspectorReturnFocus.focus();inspectorReturnFocus=null};
function inspectorBack(){if(inspectorTrail.length){inspectorCurrent=inspectorTrail.pop();renderInspector()}else closeDrawer()}
function runAccessible(el,fn,kind){if(!el||el.dataset?.enhanced)return;el.dataset.enhanced='true';el.classList.add(kind);el.tabIndex=0;el.setAttribute('role','button');el.addEventListener('click',e=>{if(e.target.closest('button,input,select,textarea,a')&&e.target!==el)return;fn(e)});el.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target===el){e.preventDefault();fn(e)}})}
function augmentProduct(){if(current<0)return;const app=current;const root=$('#main');root.querySelectorAll('tbody tr').forEach(tr=>{const b=tr.querySelector('button');if(b){runAccessible(tr,()=>b.click(),'interactive-record')}else if(!tr.querySelector('input,select,textarea')){const vals=[...tr.querySelectorAll('td')].map(x=>x.textContent.trim());if(vals.length)runAccessible(tr,()=>inspectTableRow(app,vals),'interactive-record')}});root.querySelectorAll('.slimstat,.stat,.sales-metric,.engagement-kpis>div,.forecastcompare>div,.roiresult').forEach(el=>{const label=el.querySelector('label,small,.micro-label')?.textContent?.trim()||'Business case';const value=el.querySelector('strong,h1,b')?.textContent?.trim()||'';runAccessible(el,()=>inspectMetric(app,label,value),'interactive-metric')});root.querySelectorAll('svg.chart,.ring,.bars,.pipeline-funnel,.heatmap,.capacityheat,.waterfall,.microbars,.pipelinebar').forEach(el=>{const label=el.closest('.surface,.card')?.querySelector('h2')?.textContent?.trim()||'Scenario detail';runAccessible(el,()=>inspectChart(app,label),'interactive-chart');el.setAttribute('aria-label',label+' — open underlying data');if(app===5&&el.tagName.toLowerCase()==='svg'){el.querySelectorAll('circle').forEach((c,i)=>{c.style.cursor='pointer';c.addEventListener('click',e=>{e.stopPropagation();monthlyRevenue(i)})})}});root.querySelectorAll('.filechip').forEach(el=>{const name=el.querySelector('b')?.textContent||el.textContent.trim();runAccessible(el,()=>openFileRecord(app,name),'interactive-file')});root.querySelectorAll('.tablewrap thead th').forEach((th,i)=>{if(!th.textContent.trim())return;th.classList.add('sortable-heading');th.tabIndex=0;th.addEventListener('click',()=>sortVisibleTable(th,i));th.addEventListener('keydown',e=>{if(e.key==='Enter')sortVisibleTable(th,i)})});if(app===0&&tab===1)enhanceProposalEditor();if(app===1&&tab===1)enhanceEmailEditor();if(app===12&&tab===0)enhanceOutreachEditor();root.querySelectorAll('#sidebar button').forEach(b=>b.title=b.textContent.trim());}
function sortVisibleTable(th,i){const body=th.closest('table').querySelector('tbody');const rows=[...body.rows];const direction=th.dataset.sort==='asc'?-1:1;th.dataset.sort=direction===1?'asc':'desc';rows.sort((a,b)=>{const x=a.cells[i]?.textContent.trim()||'',y=b.cells[i]?.textContent.trim()||'';const nx=Number(x.replace(/[$,% ]/g,'')),ny=Number(y.replace(/[$,% ]/g,''));return direction*(x&&y&&Number.isFinite(nx)&&Number.isFinite(ny)?nx-ny:x.localeCompare(y))}).forEach(r=>body.appendChild(r))}
const renderBeforeFinish=render;
render=function(){renderBeforeFinish();augmentProduct();if(current>=0){const toolbar=$('.presentation-bar');if(toolbar&&!toolbar.querySelector('.tour-trigger'))toolbar.insertAdjacentHTML('beforeend',btn(icon('arrow')+' Walk through','startWalkthrough()','tour-trigger'))}renderWalkthrough()};
function inspectMetric(app,label,value){const name=toolsList[app][0];let details='';if(app===4){details=table(['Department','Annual plan','Prior year'],['Operations','Marketing','Technology','People'].map((d,i)=>[ib(d,`budgetDetail(${i})`,'arrow','link'),money(state.budget[i]),money([160000,80000,55000,45000][i])]))}else if(app===5){details=table(['Opportunity','Value','Stage'],state.deals.map((d,i)=>[ib(d.company,`editDealSaas(${i})`,'arrow','link'),money(d.value),tag(d.stage)]))}else if(app===1){details=table(['Attendee','Engagement','Intent'],people.map((p,i)=>[ib(p[0],`state.selectedPerson=${i};closeDrawer();tab=1;render()`,'arrow','link'),p[4],p[3]]))}else if(app===6){details=table(['Team member','Assigned hours','Capacity'],state.team.map((t,i)=>[ib(t[0],`editAssignmentSaas(${i})`,'arrow','link'),t[2],40]))}else if(app===9){details=table(['Driver','Value'],[['Baseline revenue','$3.84M'],['Pipeline growth',state.growth+'%'],['Win rate',state.win+'%'],['Scenario','$'+(3.84*(1+state.growth/100)*state.win/32).toFixed(2)+'M']])}else if(app===10){const r=roiValues();details=table(['Value driver','Current estimate'],[['Hours saved',state.hours+' / week'],['Adoption',state.adoption+'%'],['Annual gross benefit',money(r.gross)],['Annual running cost',money(state.running*12)],['Build investment',money(state.build)],['Year-one net',money(r.year)]])}else if(app===11){details=table(['Initiative','Status'],projects.map((p,i)=>[ib(p,`openProjectRecord(${i})`,'arrow','link'),tag([1,4].includes(i)?'Needs attention':'On track')]))}else if(app===12){details=table(['Company','Fit','Action'],companies.map((c,i)=>[c,[94,89,86,82][i],ib('Open company',`state.company=${i};closeDrawer();tab=0;render()`,'arrow')]))}else if(app===8){details=table(['Report','Business function',''],reports.map(r=>[r[0],r[1],ib('Explore',`closeDrawer();nav(${r[3]})`,'arrow')]))}else{details=table(['Dimension','Context'],[['Workspace',name],['Metric',label],['Current result',value||'See the active workspace'],['Data source','Illustrative demonstration data']])}draw(label,`<div class="inspector-metrics"><div class="mini-stat"><label>CURRENT VALUE</label><strong>${esc(value||'Explore')}</strong><small>${name}</small></div><div class="mini-stat"><label>CONTEXT</label><strong style="font-size:21px">Sample data</strong><small>Click a record below to explore</small></div></div>${details}<p class="detail-explanation">This view connects the headline to its underlying sample records. Editable records retain your changes in this session.</p>`)}
function inspectChart(app,label){if(app===5){draw(label,`<p class="detail-explanation">Explore the data behind the chart. Select a month for a closer look.</p>${table(['Month','Revenue','Prior year','Change'],[1.5,1.7,1.8,2.15,2.1,2.7,2.55,2.95,3.1,3.5,3.65,3.84].map((n,i)=>[ib(['January','February','March','April','May','June','July','August','September','October','November','December'][i],`monthlyRevenue(${i})`,'arrow','link'),'$'+n.toFixed(2)+'M','$'+(n*.89).toFixed(2)+'M','+12.4%']))}${ib('Open opportunity workspace','closeDrawer();tab=1;render()','arrow','primary')}`);return}if(app===6){availabilityDialog();return}if(app===9){forecastLibrary();return}if(app===10){roiMethodology();return}if(app===8){draw(label,`<div class="reference-box">${icon('insights')}<h3>Trace the insight to its report.</h3><p>Choose the source report to explore the records and assumptions behind this view.</p></div>${reports.map(r=>`<div class="proof-row"><div><b>${r[0]}</b><p>${r[2]}</p></div>${ib('Open',`closeDrawer();nav(${r[3]})`,'arrow')}</div>`).join('')}`);return}inspectMetric(app,label,'View data')}
function monthlyRevenue(i){let n=[1.5,1.7,1.8,2.15,2.1,2.7,2.55,2.95,3.1,3.5,3.65,3.84][Math.min(i,11)]||3.84;const month=['January','February','March','April','May','June','July','August','September','October','November','December'][Math.min(i,11)]||'December';draw(month+' revenue',`<div class="inspector-metrics"><div class="mini-stat"><label>REVENUE</label><strong>$${n.toFixed(2)}M</strong><small>Illustrative monthly value</small></div><div class="mini-stat"><label>COMPARISON PERIOD</label><strong>$${(n*.89).toFixed(2)}M</strong><small>Prior-year sample</small></div></div>${table(['Segment','Revenue'],[['Professional services','$'+(n*.42).toFixed(2)+'M'],['Manufacturing','$'+(n*.30).toFixed(2)+'M'],['Financial services','$'+(n*.20).toFixed(2)+'M'],['Other','$'+(n*.08).toFixed(2)+'M']])}<div class="detail-explanation">Open the deal workspace to review and edit individual opportunities that influence future revenue.</div>${ib('Review opportunities','closeDrawer();tab=1;render()','arrow','primary')}`)}
function inspectTableRow(app,values){if(app===4){let i=['Operations','Marketing','Technology','People'].findIndex(x=>values[0].includes(x));if(i>=0){budgetDetail(i);return}}if(app===3){let i=panelNames.findIndex(n=>values[0].includes(n));if(i>=0){personaDetail(i);return}}if(app===9){draw(values[0],table(['Scenario attribute','Value'],values.slice(1).map((v,i)=>[['Revenue','Growth & conversion','Additional context'][i]||'Detail',v]))+ib('Open scenario library','forecastLibrary()','arrow','primary'));return}draw(values[0],`<span class="sourcebadge">${toolsList[app][0]}</span><div class="reference-box">${values.slice(1).map((v,i)=>`<div class="proof-row"><span>${['Status / value','Context','Owner / timing','Detail'][i]||'Additional detail'}</span><b>${esc(v)}</b></div>`).join('')}</div><p class="detail-explanation">This is a sample record in the current workspace.</p>`)}
function openFileRecord(app,name){if(app===7){let files=['Pilot brief.pdf','Data mapping.xlsx','Dashboard preview.pdf','Workshop notes.docx',...(state.localFiles||[])];let i=files.findIndex(f=>name.includes(f));previewWorkspaceFile(Math.max(0,i));return}if(app===0){draw(name,`<div class="paper"><span class="micro-label">NINE-67 / SOURCE MATERIAL</span><div class="rule"></div><h2>Operations modernization</h2><p>Deliver a 90-day pilot that connects reporting inputs, ownership, exceptions, and next actions into a shared workspace.</p><h3>Key requirements</h3><p>First working iteration in two weeks.<br>Budget ceiling of $75,000.<br>Named delivery owner.<br>Defined success measures.<br>Source permissions preserved.</p><div class="paperfoot">ILLUSTRATIVE SOURCE PREVIEW</div></div><div class="form-actions"><span class="subtle">12 requirements identified</span>${ib('Review coverage','closeDrawer();tab=2;render()','arrow','primary')}</div>`);return}draw(name,`<div class="reference-box">${icon('file')}<h3>${esc(name)}</h3><p>Supporting source selected for ${toolsList[app][0]}. This demonstration uses illustrative content.</p></div>${ib('Open related workflow','closeDrawer();tab=1;render()','arrow','primary')}`)}
function enhanceProposalEditor(){const toolbar=$('#main .toolbar');if(toolbar)toolbar.outerHTML=`<div class="editor-toolbar">${btn('<b>B</b>',"formatProposal('bold')")}${btn('<i>I</i>',"formatProposal('italic')")}${btn('H₂',"formatProposal('heading')")}<span class="divider"></span>${btn('• List',"formatProposal('list')")}${ib('Insert section','insertProposalSection()','plus')}${ib('Preview','previewProposal()','file')}</div>`;const input=$('#proposalText');if(input){input.addEventListener('input',()=>{state.drafts[state.section]=input.value;persist()});}const preview=$('#previewText');if(preview){preview.innerHTML=proposalMarkup(state.drafts[state.section]||proposalText());if(input)input.addEventListener('input',()=>preview.innerHTML=proposalMarkup(input.value))}}
function proposalMarkup(s){return esc(s).replace(/^## (.+)$/gm,'<h3>$1</h3>').replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\*(.+?)\*/g,'<em>$1</em>').replace(/^- (.+)$/gm,'• $1').replaceAll('\n','<br>')}
function formatProposal(kind){const el=$('#proposalText');if(!el)return;let a=el.selectionStart||0,b=el.selectionEnd||a;let selection=el.value.slice(a,b)||({bold:'Important text',italic:'Emphasized text',heading:'Section heading',list:'List item'}[kind]);let replacement=kind==='bold'?'**'+selection+'**':kind==='italic'?'*'+selection+'*':kind==='heading'?'\n## '+selection+'\n':'\n- '+selection;el.value=el.value.slice(0,a)+replacement+el.value.slice(b);state.drafts[state.section]=el.value;persist();$('#previewText').innerHTML=proposalMarkup(el.value);el.focus()}
function insertProposalSection(){draw('Insert a proposal block',`${['Success measures','Acceptance criteria','Project governance','Scope exclusions'].map((x,i)=>`<div class="proof-row"><div><b>${x}</b><p>${['Baseline, adoption, and measurable outcomes.','How the project owner will approve delivery.','Review cadence, decisions, and escalation.','Clarify what is outside the agreed scope.'][i]}</p></div>${ib('Insert',`addProposalBlock(${i})`,'plus')}</div>`).join('')}`)}
function addProposalBlock(i){const blocks=['## Success measures\nBaseline reporting time, weekly active usage, and data completeness will be measured during the pilot.','## Acceptance criteria\nThe project owner will review the working application against the agreed requirements before sign-off.','## Project governance\nA named owner will attend a fortnightly review, confirm priorities, and record decisions in the shared workspace.','## Scope exclusions\nNew data sources and workflows outside the agreed pilot will be scoped separately.'];state.drafts[state.section]=(state.drafts[state.section]||proposalText())+'\n\n'+blocks[i];closeDrawer();render();saved('Proposal block inserted')}
function previewProposal(){draw('Document preview',`<div class="paper"><div class="row"><b>Nine-67</b><span class="subtle">PROPOSAL</span></div><div class="rule"></div><h2>${sections[state.section]}</h2><div style="font-size:13px;line-height:1.9">${proposalMarkup(state.drafts[state.section]||proposalText())}</div><div class="paperfoot">${state.section+1} / ${sections.length} · WORKING DRAFT</div></div>${ib('Export full proposal','exportProposal()','download','primary')}`)}
refineProposal=function(){const original=$('#proposalText')?.value||state.drafts[state.section]||proposalText();state.pendingRefinement=original+'\n\n## Measurable acceptance\nThe project owner will review a working demonstration every two weeks, compare the result with the agreed baseline, and approve the next set of priorities.';draw('Review the proposed refinement',`<span class="sourcebadge">SIMULATED AI SUGGESTION</span><h2 style="margin-top:23px">A clearer acceptance standard</h2><p class="detail-explanation">The suggestion adds a named review cadence and a measurable basis for approval. Review it before applying.</p><div class="revision-original">${esc(original.slice(-300))}</div><div class="revision-proposed">${esc(state.pendingRefinement.slice(original.length))}</div><div class="form-actions">${ib('Keep current version','closeDrawer()','file')}${ib('Apply refinement','state.drafts[state.section]=state.pendingRefinement;closeDrawer();render();saved("Proposal refinement applied")','check','primary')}</div>`)};
function enhanceEmailEditor(){const subject=$('#mailSubject');if(subject){const key=state.selectedPerson+'-'+state.emailDay;if(state.emailSubjects[key])subject.value=state.emailSubjects[key];subject.addEventListener('input',()=>{state.emailSubjects[key]=subject.value;persist()})}$('#main').querySelectorAll('button').forEach(b=>{if(b.textContent.trim()==='Save draft')b.onclick=saveEmailDraft;if(b.textContent.includes('Approve sequence'))b.onclick=approveEmailSequence});const body=$('#mailText');if(body)body.addEventListener('input',()=>{state.drafts['mail'+state.selectedPerson+state.emailDay]=body.value;persist()})}
function saveEmailDraft(){if($('#mailSubject'))state.emailSubjects[state.selectedPerson+'-'+state.emailDay]=$('#mailSubject').value;if($('#mailText'))state.drafts['mail'+state.selectedPerson+state.emailDay]=$('#mailText').value;saved('Email draft saved');const b=[...$('#main').querySelectorAll('button')].find(x=>x.textContent==='Save draft');if(b){b.innerHTML=icon('check')+' Saved';b.classList.add('success-chip')}}
function approveEmailSequence(){saveEmailDraft();state.sequenceApprovals[state.selectedPerson]=true;draw('Sequence approved',`<div class="action-complete">${icon('check')}<h2>${people[state.selectedPerson][0]}’s sequence is ready.</h2><p>Four emails have been marked approved in this demonstration. Nothing has been sent.</p></div>${table(['Message','Timing','Status'],['Webinar recap','Useful next step','Practical example','Conversation invitation'].map((x,i)=>[x,'Day '+[0,3,7,14][i],tag('Approved','green')]))}<div class="form-actions">${ib('Continue editing','closeDrawer()','file')}${ib('Review audience groups','closeDrawer();tab=2;render()','arrow','primary')}</div>`);persist()}
emailDetail=function(i,day=0){state.selectedPerson=i;state.emailDay=day;closeDrawer();tab=1;render()};
const personaProfiles=[{name:'Executive sponsor',initials:'AM',score:87,focus:'Strategic alignment and accountable outcomes',reaction:'The focused first iteration is compelling. I need to know who owns the business outcome and what will demonstrate progress.',questions:['Which outcome is the executive team prioritizing?','Who is accountable for adoption and benefits?','What decision will the first pilot review enable?'],edit:'Name the executive sponsor and agree on two measurable outcomes before kickoff.'},{name:'Finance decision-maker',initials:'JE',score:72,focus:'Cost, evidence, and realized value',reaction:'The idea could be useful, but the financial case needs a clear baseline. Time saved is only valuable if the team can redeploy it.',questions:['What is the full build and annual running cost?','How were the time-saving assumptions established?','What changes if adoption is only 50%?'],edit:'Include a conservative business case and separate build, cloud, model, and maintenance costs.'},{name:'IT & security leader',initials:'TK',score:76,focus:'Data access, integration, and ownership',reaction:'I want the proposed data flow and permission model to be explicit before the build begins.',questions:['Which systems and fields will the application access?','How will existing user permissions be preserved?','Who will own monitoring, maintenance, and change control?'],edit:'List approved sources, access boundaries, and ownership of the application and integrations.'},{name:'Frontline team member',initials:'SR',score:91,focus:'Daily usability and team adoption',reaction:'A shared view could reduce the time we spend chasing status. Show me how this changes the work I do every day.',questions:['What existing step will this replace?','Will I enter the same information twice?','How can the team influence the first iteration?'],edit:'Describe a before-and-after workflow and include a small team of real users in the first review.'},{name:'Procurement reviewer',initials:'CL',score:78,focus:'Scope, commitments, and acceptance',reaction:'The phased approach is clear. I need defined deliverables and acceptance criteria, including what is excluded.',questions:['What is delivered by the end of each phase?','What constitutes acceptance?','How will new requests and scope changes be handled?'],edit:'Add an acceptance checklist, scope exclusions, and a documented change process.'}];
personaDetail=function(i){const p=personaProfiles[i];const score=Math.min(97,p.score+(state.simulation===2?6:0));draw(p.name,`<div class="person"><div class="portrait" style="margin:0">${p.initials}</div><div><b style="font-size:13px">${p.focus}</b><p class="subtle">Simulated persona · ${esc(state.simIndustry)}</p></div></div><div class="inspector-metrics"><div class="mini-stat"><label>RESPONSE SCORE</label><strong>${score}<span style="font-size:13px"> / 100</span></strong><small>Directional sample assessment</small></div><div class="mini-stat"><label>PRIMARY LENS</label><strong style="font-size:19px;line-height:1.4">${p.focus}</strong></div></div><div class="callout"><b>In their words</b><br>${p.reaction}</div><h2 style="margin-top:25px">Questions they would ask</h2>${p.questions.map((q,j)=>`<div class="proof-row"><span class="micro-label">0${j+1}</span><b>${q}</b></div>`).join('')}<div class="reference-box"><span class="micro-label">RECOMMENDED IMPROVEMENT</span><p>${p.edit}</p></div><div class="form-actions">${ib('Test another perspective','inspectorBack()','simulation')}${ib('Apply to revision',`applyPersonaFeedback(${i})`,'check','primary')}</div>`)};
function applyPersonaFeedback(i){state.simRevised=(state.simRevised||state.simcontent)+'\n\n'+personaProfiles[i].edit;closeDrawer();tab=2;render();saved('Persona feedback added to your revision')}
const originalAssignment=assignment;assignment=function(i){editAssignmentSaas(i)};
projectDetail=function(i){openProjectRecord(i)};
budgetDetail=function(i){const n=['Operations','Marketing','Technology','People'][i],total=state.budget[i];draw(n+' budget',`<span class="sourcebadge">FY 2027 / DEPARTMENT PLAN</span><div class="inspector-metrics"><div class="mini-stat"><label>ANNUAL PLAN</label><strong>${money(total)}</strong></div><div class="mini-stat"><label>PRIOR YEAR</label><strong>${money([160000,80000,55000,45000][i])}</strong></div></div>${field('Annual department budget','deptBudget',total,'number')}${table(['Allocation','Share','Amount'],[['People & delivery','65%',money(total*.65)],['Tools & infrastructure','25%',money(total*.25)],['Contingency','10%',money(total*.1)]])}<div class="form-actions">${ib('Open workbook',`state.budgetDept=${i};closeDrawer();tab=1;render()`,'budget')}${ib('Save budget',`state.budget[${i}]=Math.max(0,+document.getElementById('deptBudget').value);closeDrawer();render();saved('Department budget updated')`,'check','primary')}</div>`)};
function assignmentWorkflow(i=state.lead){let p=people[i];let existing=state.contactAssignments[i];draw('Assign '+p[2],`<div class="reference-box"><div class="person">${ava(p[0])}<div><b>${p[0]}</b><p style="margin:4px 0">${p[1]} · ${p[2]}</p></div></div></div><label class="field">Account owner<select id="assignLeadOwner">${['Alex Morgan','Jordan Ellis','Taylor Kim'].map(n=>`<option ${existing?.owner===n?'selected':''}>${n}</option>`).join('')}</select></label>${field('Follow-up date','assignLeadDate',existing?.date||'2026-10-21','date')}<label class="field">Recommended next action<textarea id="assignLeadTask">${esc(existing?.task||'Invite '+p[0].split(' ')[0]+' to a discovery conversation focused on the reporting workflow.')}</textarea></label><div class="form-actions"><span class="subtle">Creates a task in this demonstration.</span>${ib('Assign & create task',`saveLeadAssignment(${i})`,'check','primary')}</div>`)}
function saveLeadAssignment(i){const data={owner:$('#assignLeadOwner').value,date:$('#assignLeadDate').value,task:$('#assignLeadTask').value};if(!data.date||!data.task.trim()){toast('Add a date and next action');return}state.contactAssignments[i]=data;state.assignedLead=i;state.followups=state.followups.filter(x=>x.lead!==i);state.followups.push({...data,lead:i});persist();draw('Lead assigned',`<div class="action-complete">${icon('check')}<h2>${people[i][2]} has a next step.</h2><p>${esc(data.owner)} owns the follow-up on ${esc(data.date)}.</p></div><div class="reference-box"><span class="micro-label">FOLLOW-UP TASK</span><p>${esc(data.task)}</p></div>${ib('Return to lead','closeDrawer();render()','arrow','primary')}`);saved('Lead assigned and follow-up task created')}
function openLeadFollowups(){draw('Sales follow-up tasks',state.followups.length?table(['Account','Owner','Due',''],state.followups.map(f=>[people[f.lead][2],f.owner,f.date,ib('Open',`assignmentWorkflow(${f.lead})`,'arrow')])):'<div class="empty-action">No follow-up tasks yet.<br>Select a lead and assign the next action.</div>')}
function enhanceOutreachEditor(){const pane=$('#main .draftpane');if(!pane)return;const ready=[...pane.querySelectorAll('button')].find(b=>b.textContent.includes('Mark ready')||b.textContent.trim()==='Ready ✓');if(ready)ready.onclick=reviewOutreach;const subject=$('#outSubject');if(subject)subject.addEventListener('input',persist);const content=$('#outreach');if(content)content.addEventListener('input',persist)}
function reviewOutreach(){saveOutreach2();const key=state.company+state.channel+state.variant;const subject=$('#outSubject')?.value||state.drafts['subject'+key]||'One workflow idea for '+companies[state.company];state.drafts['subject'+key]=subject;draw('Review outreach',`<span class="sourcebadge">${state.channel.toUpperCase()} / ${versions[state.variant].toUpperCase()}</span><h2 style="margin-top:22px">${companies[state.company]}</h2><div class="reference-box"><span class="micro-label">${state.channel==='Email'?'SUBJECT':'OPENING LINE'}</span><h3>${esc(subject)}</h3><p style="white-space:pre-wrap">${esc(state.drafts['out'+key]||outreachText())}</p></div><div class="proof-row"><div><b>Relevant business context</b><p>The message connects to the sample company signal.</p></div><span class="tick">✓</span></div><div class="proof-row"><div><b>Human review</b><p>Confirm the claim, contact, and selected message angle.</p></div><input type="checkbox" id="outreachReviewed" class="rowcheck" aria-label="Confirm outreach review"></div><div class="form-actions">${ib('Keep editing','closeDrawer()','file')}${ib('Approve draft',`approveOutreach('${key}')`,'check','primary')}</div><p class="detail-explanation">Approval is local to this demonstration. No outreach is sent.</p>`)}
function approveOutreach(key){if(!$('#outreachReviewed').checked){toast('Confirm that you reviewed the draft');return}state.drafts['ready'+key]=true;closeDrawer();render();saved('Outreach draft approved for review')}
async function researchWorkflow(){draw('Nightwatch research run',`<p class="detail-explanation">Running the sample research workflow against your saved brief.</p><div class="research-progress"><i id="runProgress" style="width:0%"></i></div><div class="research-run">${[['Company discovery','Industry, size, geography, and signal relevance.'],['Account qualification','Match the company to the workflow opportunity.'],['Context & contact review','Prepare the research context and target role.'],['Draft generation','Build three email and LinkedIn approaches.']].map(([x,y],i)=>`<div class="run-step" id="runStep${i}"><span class="run-icon">${i+1}</span><div><b>${x}</b><small>${y}</small></div></div>`).join('')}</div><div id="runResult"></div>`);for(let i=0;i<4;i++){await new Promise(r=>setTimeout(r,320));const el=$('#runStep'+i);if(!el)return;el.classList.add('complete');el.querySelector('.run-icon').textContent='✓';$('#runProgress').style.width=((i+1)*25)+'%'}state.night=true;state.researchRuns.push({at:new Date().toISOString(),companies:4,versions:12});persist();$('#runResult').innerHTML=`<div class="action-complete">${icon('check')}<h2>Four sample accounts are ready.</h2><p>Research context and three outreach angles are available for each company.</p></div>${ib('Explore the companies','closeDrawer();tab=0;render()','arrow','primary')}`;saved('Sample research run completed')}
function teamMemberProfile(name){const member=state.team.find(x=>x[0]===name);const tasks=state.board.filter(t=>t.owner===name);draw(name,`<div class="person">${ava(name)}<div><b>${member?.[1]||'Project stakeholder'}</b><p class="subtle">Nine-67 demonstration workspace</p></div></div><div class="inspector-metrics"><div class="mini-stat"><label>ASSIGNED TASKS</label><strong>${tasks.length}</strong></div><div class="mini-stat"><label>WEEKLY LOAD</label><strong>${member?member[2]+' hrs':'Shared access'}</strong></div></div>${tasks.length?table(['Task','Status',''],tasks.map(t=>[t.name,tag(['To do','In progress','Complete'][t.stage]),ib('Open',`editBoardTask(${state.board.indexOf(t)})`,'arrow')])):'<div class="empty-action">No assigned board tasks in this sample view.</div>'}${member?ib('Edit allocation',`editAssignmentSaas(${state.team.indexOf(member)})`,'resources','primary'):ib('View project access','closeDrawer();nav(7);tab=3;render()','user','primary')}`)}
forecastChart=function(v){let max=Math.ceil(Math.max(v,3.84)*1.15),Y=n=>225-n/max*185,X=i=>45+i*120;let actual=[3.42,3.65,3.84],scenario=[3.84+(v-3.84)/3,3.84+(v-3.84)*2/3,v];const coords=actual.map((n,i)=>`${X(i)},${Y(n)}`).join(' ');const future=[[X(2),Y(3.84)],...scenario.map((n,i)=>[X(i+3),Y(n)])].map(p=>p.join(',')).join(' ');return `<svg viewBox="0 0 700 275" class="chart" style="height:310px" role="img" aria-label="Revenue scenario with dynamic scale"><rect x="335" y="18" width="330" height="210" fill="#faf6eb"/>${[0,1,2,3,4].map(i=>{let n=max*i/4;return `<line x1="42" x2="665" y1="${Y(n)}" y2="${Y(n)}" stroke="#e8e4d8"/><text x="0" y="${Y(n)+4}" fill="#a79a80" font-size="10">$${n.toFixed(1)}M</text>`}).join('')}<text x="435" y="32" fill="#b59d72" font-size="9" letter-spacing="1">SCENARIO PERIOD</text><polyline points="${coords}" stroke="#ae8447" stroke-width="3" fill="none"/><line x1="${X(2)}" y1="${Y(3.84)}" x2="${X(5)}" y2="${Y(3.84)}" stroke="#b7b3a6" stroke-dasharray="5 5" stroke-width="2"/><polyline points="${future}" stroke="#ae8447" stroke-width="3" stroke-dasharray="6 4" fill="none"/>${[...actual,...scenario].map((n,i)=>`<circle cx="${X(i)}" cy="${Y(n)}" r="4" fill="white" stroke="#ae8447" stroke-width="2"><title>${['Oct','Nov','Dec','Jan','Feb','Mar'][i]}: $${n.toFixed(2)}M</title></circle>`).join('')}${['Oct','Nov','Dec','Jan','Feb','Mar'].map((x,i)=>`<text x="${X(i)-9}" y="257" fill="#a79a80" font-size="10">${x}</text>`).join('')}</svg>`};
function roiWaterfall(){let r=roiValues(),lo=Math.min(0,r.year),hi=Math.max(r.gross,state.build+state.running*12,1);let pad=(hi-lo)*.12;let max=hi+pad,min=lo-pad;let y=n=>175-(n-min)/(max-min)*150;let starts=[0,r.gross,r.net,0],ends=[r.gross,r.net,r.year,r.year],labels=['Benefit','Running cost','Build cost','Net value'],amounts=[r.gross,-state.running*12,-state.build,r.year];return `<svg viewBox="0 0 470 225" style="width:100%;height:215px" role="img" aria-label="Project investment waterfall"><line x1="20" x2="450" y1="${y(0)}" y2="${y(0)}" stroke="#dbd3c1"/>${labels.map((x,i)=>`<rect x="${28+i*112}" y="${Math.min(y(starts[i]),y(ends[i]))}" width="70" height="${Math.max(3,Math.abs(y(starts[i])-y(ends[i])))}" rx="3" fill="${['#b2bf95','#d5c09a','#c4a77c',r.year>0?'#9caa78':'#b28465'][i]}"><title>${x}: ${money(amounts[i])}</title></rect><text x="${63+i*112}" y="${Math.min(y(starts[i]),y(ends[i]))-8}" text-anchor="middle" fill="#a18b64" font-size="10">${money(amounts[i])}</text><text x="${63+i*112}" y="210" text-anchor="middle" fill="#a18b64" font-size="10">${x}</text>`).join('')}</svg>`}
const originalUpdateRoi=updateRoi;updateRoi=function(){originalUpdateRoi();const chart=$('#main .waterfall');if(chart){chart.style.display='block';chart.style.height='215px';chart.innerHTML=roiWaterfall()}persist()};
const originalUpdateForecast=updateForecast;updateForecast=function(){originalUpdateForecast();const chart=$('#forecastChart svg.chart');if(chart)runAccessible(chart,()=>inspectChart(9,'Revenue scenario'),'interactive-chart');document.querySelectorAll('#main .legend > span').forEach(el=>el.style.opacity='1');persist()};
const basicAugment=augmentProduct;augmentProduct=function(){basicAugment();if(current<0)return;const root=$('#main');root.querySelectorAll('.avatar[title]').forEach(el=>{const n=el.getAttribute('title');runAccessible(el,e=>{e.stopPropagation();teamMemberProfile(n)},'interactive-record')});if(current===2&&tab===0){const b=root.querySelector('.actionpane button.primary');if(b){b.onclick=()=>assignmentWorkflow();b.textContent=state.contactAssignments[state.lead]?'View assignment':'Assign & create follow-up'}const status=$('#assignStatus');if(status&&state.contactAssignments[state.lead])status.textContent='Assigned to '+state.contactAssignments[state.lead].owner+' · '+state.contactAssignments[state.lead].date;const pane=root.querySelector('.actionpane');if(pane&&!pane.querySelector('[data-followups]'))pane.insertAdjacentHTML('beforeend','<div data-followups style="margin-top:18px">'+ib('View follow-up tasks','openLeadFollowups()','list')+'</div>')}if(current===12){root.querySelectorAll('button').forEach(b=>{if(b.textContent.includes('Run research'))b.onclick=researchWorkflow})}if(current===10&&tab!==1){const chart=root.querySelector('.waterfall');if(chart){chart.style.display='block';chart.style.height='215px';chart.innerHTML=roiWaterfall()}}if(current===9){root.querySelectorAll('svg.chart circle').forEach(c=>{const clone=c.cloneNode(true);c.replaceWith(clone)})}root.querySelectorAll('.legend > span,.chartlegend > span').forEach((el,i)=>{const surface=el.closest('.surface,.card');const lines=surface?.querySelectorAll('svg polyline,svg path');if(lines?.length){el.style.cursor='pointer';el.title='Toggle series';el.onclick=()=>{const currentLines=surface.querySelectorAll(current===9?'svg polyline,svg line[stroke-dasharray]':'svg polyline,svg path');const seriesIndex=current===9?[0,2,1][i]:i;const line=currentLines[Math.min(seriesIndex,currentLines.length-1)];if(!line)return;const off=line.style.opacity==='0.15';line.style.opacity=off?'1':'0.15';el.style.opacity=off?'1':'.45'}}});};
