let walkthrough=null;
function startWalkthrough(){walkthrough={app:current,step:0};tab=walkthroughs[current][0][2];render()}
function moveWalkthrough(delta){if(!walkthrough)return;walkthrough.step+=delta;if(walkthrough.step>2){walkthrough=null;render();return}walkthrough.step=Math.max(0,walkthrough.step);current=walkthrough.app;tab=walkthroughs[current][walkthrough.step][2];closeDrawer();render()}
function renderWalkthrough(){let old=document.getElementById('walkthroughDock');if(old)old.remove();if(!walkthrough||walkthrough.app!==current)return;let s=walkthroughs[current][walkthrough.step];let dock=document.createElement('aside');dock.id='walkthroughDock';dock.className='tour-dock';dock.innerHTML=`<div class="tour-top"><span class="micro-label">PRODUCT WALKTHROUGH · ${walkthrough.step+1} OF 3</span>${btn('Close','walkthrough=null;render()')}</div><h3>${s[0]}</h3><p>${s[1]}</p><div class="tour-bottom">${btn('Back','moveWalkthrough(-1)')}${btn(walkthrough.step===2?'Finish':'Next step','moveWalkthrough(1)','primary')}</div>`;document.body.appendChild(dock)}
render();
